1	import type { Metadata } from "next";
2	import { db } from "@/lib/db";
3	import { GAME_FAMILIES } from "@/lib/games";
4	import { currentPromo } from "@/lib/promotions";
5	import { firstMonthFreeAppliesTo } from "@/lib/promo-redemption";
6	import { annualDiscountPct } from "@/lib/annual-discount";
7	import { backupPlusMonthlyCents } from "@/lib/backup-upgrade";
8	import { extraDiskPerGbCents } from "@/lib/disk-expand";
9	import { AmbientField } from "@/components/marketing/AmbientField";
10	import { ReviewBadges } from "@/components/marketing/ReviewBadges";
11	import { POPULAR_TLDS } from "@/components/marketing/tlds";
12	import { ProductJsonLd, FaqJsonLd } from "@/components/marketing/StructuredData";
13	import {
14	  PricingExplorer,
15	  type ExplorerPlan,
16	  type ExplorerGameFamily,
17	  type ProductId,
18	} from "@/components/marketing/PricingExplorer";
19	
20	export const dynamic = "force-dynamic";
21	
22	export const metadata: Metadata = {
23	  title: "Pricing",
24	  description:
25	    "One place to compare every Nxeon product — Cloud VPS, game servers, shared web hosting, business email and domains. Live catalogue prices, monthly billing, no lock-in.",
26	  alternates: { canonical: "/pricing" },
27	};
28	
29	/* Deploy CTA target — the same href the previous pricing page's plan CTAs used. */
30	const DEPLOY_HREF = "/register";
31	const DOMAINS_HREF = "/domains";
32	
33	function gb(mb: number): string {
34	  return `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
35	}
36	/** Base MONTHLY price for a plan. VPS/Hosting store a monthly `priceCents`; Email &
37	 *  Game store it per `termMonths`, so normalise to a per-month figure. All display
38	 *  math downstream runs THIS through termPriceCents — the formula checkout charges. */
39	function monthlyOf(p: { priceCents: number; termMonths?: number }): number {
40	  const t = p.termMonths ?? 1;
41	  return t > 1 ? Math.round(p.priceCents / t) : p.priceCents;
42	}
43	
44	const INCLUDED: Record<ProductId, string[]> = {
45	  vps: ["Full root access", "Dedicated IPv4", "NVMe SSD", "DDoS protection", "Auto backups", "1-click reinstall"],
46	  game: ["DDoS protection", "Full control panel", "Instant deploy", "Game file manager", "Custom jar support"],
47	  hosting: ["Free SSL", "1-click WordPress", "Free migration", "cPanel included", "DDoS protection"],
48	  email: ["Webmail + IMAP/SMTP", "Spam & virus filtering", "Shared calendars & contacts", "Automatic MX/SPF setup"],
49	  domains: ["Free WhoisGuard privacy", "Full DNS management", "One-click VPS pointing", "Auto-renew"],
50	};
51	
52	const FAQ = [
53	  { q: "How does billing work across products?", a: "Every Nxeon product — VPS, game servers, shared hosting, business email and domains — is prepaid from your wallet balance, monthly by default. VPS also offers optional annual and multi-year terms at a discount. Whatever term you choose, services auto-renew at exactly that same price — the price you sign up at is the price you renew at — and nothing locks you in: cancel anytime and billing stops at the end of the current period." },
54	  { q: "Is the first month really free?", a: "On shared web hosting, yes — your first month is on us, then the plan renews at exactly the regular monthly price you see. The free-month offer applies to shared hosting only; VPS, game servers, business email and domains bill their regular price from month one." },
55	  { q: "Are the prices shown what I actually pay?", a: "Yes. Every price on this page is read live from the same catalogue the checkout charges from, so the number you see is the number you pay. Domain extensions show an indicative starting price — search a name for the exact live figure." },
56	];
57	
58	export default async function PricingPage() {
59	  // Every product line's prices, read LIVE from the catalogue. Nothing below is
60	  // hard-coded; a catalogue edit or deactivation propagates here automatically.
61	  const [vpsPlans, hostingPlans, emailPlans, gamePlans] = await Promise.all([
62	    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
63	    db.hostingPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
64	    db.emailPlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
65	    db.gamePlan.findMany({ where: { active: true }, orderBy: [{ sortOrder: "asc" }, { priceCents: "asc" }] }),
66	  ]);
67	
68	  // The REAL, live annual discount + add-on prices (admin settings) — never
69	  // marketing constants. These are the SAME figures lib/order.ts bills, so the
70	  // add-on builder's "your build" total is displayed === charged.
71	  const [annualPct, backupPlusCents, extraDiskGbCents] = await Promise.all([
72	    annualDiscountPct(),
73	    backupPlusMonthlyCents(),
74	    extraDiskPerGbCents(),
75	  ]);
76	
77	  // Promo copy from the single source of truth — surfaced ONLY where the owner
78	  // scoped it (shared web hosting) via firstMonthFreeAppliesTo("HOSTING"). It is
79	  // passed as a nullable label so the badge cannot render on any other product.
80	  const hostingPromoLabel = firstMonthFreeAppliesTo("HOSTING") ? currentPromo(new Date()).label : null;
81	
82	  // ── VPS: 4 tiers. Middle = "Most popular" (violet), last = "Best value" (cyan). ──
83	  const vps: ExplorerPlan[] = vpsPlans.map((p, i) => ({
84	    id: p.id,
85	    name: p.name,
86	    monthlyCents: monthlyOf(p),
87	    badge:
88	      vpsPlans.length >= 3 && i === Math.floor((vpsPlans.length - 1) / 2)
89	        ? "popular"
90	        : vpsPlans.length >= 3 && i === vpsPlans.length - 1
91	          ? "best"
92	          : undefined,
93	    specs: [
94	      { label: "CPU", value: `${p.cpuCores} vCPU` },
95	      { label: "RAM", value: gb(p.ramMB) },
96	      { label: "Storage", value: `${p.diskGB} GB NVMe` },
97	      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
98	    ],
99	    href: DEPLOY_HREF,
100	  }));
101	
102	  // ── Hosting: featured tier gets the violet "Most popular" badge. ──
103	  const hosting: ExplorerPlan[] = hostingPlans.map((p, i) => ({
104	    id: p.id,
105	    name: p.name,
106	    monthlyCents: monthlyOf(p),
107	    badge: p.featured || (hostingPlans.length >= 3 && i === Math.floor((hostingPlans.length - 1) / 2)) ? "popular" : undefined,
108	    specs: [
109	      { label: "Disk", value: `${p.diskGB} GB` },
110	      { label: "Websites", value: String(p.maxSites) },
111	      { label: "Databases", value: String(p.maxDatabases) },
112	      { label: "Bandwidth", value: `${p.bandwidthTB} TB` },
113	      { label: "Mailboxes", value: p.mailboxes < 0 ? "Unlimited" : String(p.mailboxes) },
114	    ],
115	    href: DEPLOY_HREF,
116	  }));
117	
118	  // ── Business Email: mailbox plans. ──
119	  const email: ExplorerPlan[] = emailPlans.map((p, i) => ({
120	    id: p.id,
121	    name: p.name,
122	    monthlyCents: monthlyOf(p),
123	    badge: emailPlans.length >= 3 && i === Math.floor((emailPlans.length - 1) / 2) ? "popular" : undefined,
124	    specs: [
125	      { label: "Mailboxes", value: `${p.mailboxes} mailbox${p.mailboxes === 1 ? "" : "es"}` },
126	      { label: "Storage", value: `${p.storageGB} GB / mailbox` },
127	      { label: "Filtering", value: "Spam & virus" },
128	      { label: "Sync", value: "Calendars & contacts" },
129	    ],
130	    href: DEPLOY_HREF,
131	  }));
132	
133	  // ── Game servers: grouped by family, canonical order, families with real plans only. ──
134	  const byGame = new Map<string, typeof gamePlans>();
135	  for (const g of gamePlans) {
136	    if (!byGame.has(g.gameFamily)) byGame.set(g.gameFamily, []);
137	    byGame.get(g.gameFamily)!.push(g);
138	  }
139	  const GAME_NAME: Record<string, string> = {
140	    minecraft: "Minecraft", valheim: "Valheim", rust: "Rust", palworld: "Palworld", cs2: "CS2", terraria: "Terraria",
141	  };
142	  const games: ExplorerGameFamily[] = GAME_FAMILIES.filter((f) => (byGame.get(f)?.length ?? 0) > 0).map((fam) => {
143	    const tiers = (byGame.get(fam) ?? []).slice().sort((a, b) => a.priceCents - b.priceCents);
144	    return {
145	      id: fam,
146	      name: GAME_NAME[fam] ?? fam,
147	      plans: tiers.map((t) => ({
148	        id: t.id,
149	        name: t.name,
150	        monthlyCents: monthlyOf(t),
151	        badge: t.featured ? ("popular" as const) : undefined,
152	        specs: [
153	          { label: "RAM", value: gb(t.ramMB) },
154	          { label: "CPU", value: `${t.cpuCores} vCPU` },
155	          { label: "Storage", value: `${t.diskGB} GB` },
156	          ...(t.slots != null ? [{ label: "Slots", value: `${t.slots} slots` }] : []),
157	        ],
158	        href: DEPLOY_HREF,
159	      })),
160	    };
161	  });
162	
163	  const tlds = POPULAR_TLDS.map((t) => ({ tld: t.tld, fromCents: t.fromCents }));
164	
165	  return (
166	    <>
167	      {vpsPlans.length > 0 && <ProductJsonLd plans={vpsPlans} />}
168	      <FaqJsonLd items={FAQ} />
169	
170	      <div className="relative min-h-screen overflow-hidden">
171	        {/* Ambient dot-field + violet/blue aura for depth (the v5 signature). */}
172	        <div aria-hidden className="pointer-events-none absolute inset-0 z-0">
173	          <AmbientField />
174	          <div className="absolute inset-0 hero-aura opacity-80" />
175	        </div>
176	
177	        <div className="relative z-10">
178	          <PricingExplorer
179	            annualPct={annualPct}
180	            vps={vps}
181	            hosting={hosting}
182	            email={email}
183	            games={games}
184	            tlds={tlds}
185	            hostingPromoLabel={hostingPromoLabel}
186	            included={INCLUDED}
187	            domainsHref={DOMAINS_HREF}
188	            backupPlusCents={backupPlusCents}
189	            extraDiskPerGbCents={extraDiskGbCents}
190	            reviewBadges={<ReviewBadges />}
191	          />
192	        </div>
193	      </div>
194	    </>
195	  );
196	}
