3	import Link from "next/link";
4	import { useState, type ReactNode } from "react";
5	import {
6	  VPS_TERMS,
7	  PRODUCT_TERMS,
8	  termPriceCents,
9	  termDiscountPct,
10	  vpsEffectiveMonthly,
11	} from "@/lib/billing-terms";
12	import { extraDiskCentsAt, EXTRA_DISK_STEP_GB } from "@/lib/extra-disk";
13	import {
14	  IconServer,
15	  IconGame,
16	  IconApps,
17	  IconMail,
18	  IconGlobe,
