34	/* ────────────────────────────────────────────────────────────────────────────
35	   Serializable data contract. The server page reads every plan LIVE from the
36	   catalogue (db.plan / db.gamePlan / db.hostingPlan / db.emailPlan) and hands each
37	   plan's BASE MONTHLY price down as `monthlyCents`. This component never hard-codes
38	   a price: it runs that DB number through the SAME pure money helpers checkout uses
39	   — termPriceCents / vpsEffectiveMonthly, plus extraDiskCentsAt for the storage
40	   add-on and the server-resolved backupPlusCents for the backup add-on — so what it
41	   shows for a term/add-on is exactly what checkout charges.
42	   ──────────────────────────────────────────────────────────────────────────── */
43	
44	export type ExplorerSpec = { label: string; value: string };
45	export type ExplorerPlan = {
46	  id: string;
47	  name: string;
48	  monthlyCents: number;
49	  badge?: "popular" | "best";
50	  specs: ExplorerSpec[];
51	  href: string;
52	};
53	export type ExplorerGameFamily = { id: string; name: string; plans: ExplorerPlan[] };
54	export type ExplorerTld = { tld: string; fromCents: number };
55	
56	export type ProductId = "vps" | "game" | "hosting" | "email" | "domains";
57	
58	export type PricingExplorerProps = {
59	  annualPct: number;
60	  vps: ExplorerPlan[];
61	  hosting: ExplorerPlan[];
62	  email: ExplorerPlan[];
63	  games: ExplorerGameFamily[];
64	  tlds: ExplorerTld[];
65	  /** Non-null ONLY when firstMonthFreeAppliesTo("HOSTING") — gates the hosting badge. */
66	  hostingPromoLabel: string | null;
67	  included: Record<ProductId, string[]>;
68	  domainsHref: string;
69	  /** Live add-on prices, resolved server-side from the same settings checkout bills. */
70	  backupPlusCents: number;
71	  extraDiskPerGbCents: number;
72	  /** Server-rendered <ReviewBadges /> (Trustpilot · HostAdvice · Google). */
73	  reviewBadges?: ReactNode;
74	};
75	
76	/* ── Per-service in-theme accent. Every class string is a LITERAL so Tailwind's JIT
77	   picks it up; glows/auras use inline rgba so no dynamic class is constructed. Hues:
78	   VPS=violet, Game=emerald, Hosting=cyan, Email=blue, Domains=indigo→fuchsia. ── */
79	type Accent = {
80	  icon: string;
