87	  readoutBox: string;
88	  readoutText: string;
89	  popBadge: string;
90	  popRing: string;
91	  popGlow: string;
92	  cta: string;
93	  gamePill: string;
94	};
95	const ACCENTS: Record<ProductId, Accent> = {
96	  vps: {
