177	
178	const PRODUCTS: { id: ProductId; label: string; Icon: typeof IconServer }[] = [
179	  { id: "vps", label: "Cloud VPS", Icon: IconServer },
180	  { id: "game", label: "Game Servers", Icon: IconGame },
181	  { id: "hosting", label: "Shared Hosting", Icon: IconApps },
182	  { id: "email", label: "Business Email", Icon: IconMail },
183	  { id: "domains", label: "Domains", Icon: IconGlobe },
184	];
185	function money(cents: number): string {
186	  const v = cents / 100;
187	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
188	}
189	
190	/* ── Live price for a plan at the selected term. Displayed === charged. ── */
191	function priceFor(monthlyCents: number, months: number, annualPct: number) {
192	  const perMo = vpsEffectiveMonthly(monthlyCents, months, annualPct);
193	  const total = termPriceCents(monthlyCents, months, annualPct);
194	  const savingOverTerm = monthlyCents * months - total;
195	  const savingPerYear = Math.round((monthlyCents - perMo) * 12);
196	  return { perMo, total, savingOverTerm, savingPerYear };
197	}
198	
199	export function PricingExplorer(props: PricingExplorerProps) {
200	  const { annualPct } = props;
201	  const [product, setProduct] = useState<ProductId>("vps");
202	  // Annual pre-selected by default — nudges the longer, cheaper commitment.
203	  const [months, setMonths] = useState<number>(12);
204	  const [family, setFamily] = useState<string>(props.games[0]?.id ?? "");
205	
206	  const accent = ACCENTS[product];
207	  const isVps = product === "vps";
208	  const isDomains = product === "domains";
209	  const termList = isVps ? VPS_TERMS : PRODUCT_TERMS;
210	  // Guard against an out-of-range term after a product switch (e.g. Triennial on VPS
211	  // → Business Email, which only sells Monthly/Annual). Falls back to Annual.
212	  const effMonths = termList.some((t) => t.months === months)
213	    ? months
214	    : termList.some((t) => t.months === 12)
215	      ? 12
216	      : 1;
217	  const activeIdx = Math.max(0, termList.findIndex((t) => t.months === effMonths));
218	
219	  const activeGame = props.games.find((g) => g.id === family) ?? props.games[0];
220	  const panelPlans: ExplorerPlan[] =
221	    product === "vps" ? props.vps
222	      : product === "hosting" ? props.hosting
223	      : product === "email" ? props.email
224	      : product === "game" ? (activeGame?.plans ?? [])
225	      : [];
226	
227	  // Live "from / you save" readout — the cheapest plan on the current panel.
228	  const cheapest = panelPlans.length
229	    ? panelPlans.reduce((a, b) => (b.monthlyCents < a.monthlyCents ? b : a))
230	    : null;
231	  const readout = cheapest ? priceFor(cheapest.monthlyCents, effMonths, annualPct) : null;
232	
233	  return (
234	    <div className="rail">
235	      {/* ── Compact header / wordmark ── */}
236	      <div className="flex flex-col items-center pt-14 pb-8 text-center sm:pt-20">
237	        <span className="eyebrow-pill mb-5">
238	          <span className="h-1.5 w-1.5 rounded-full bg-accent-cyan animate-pulse-dot" /> Nxeon · Pricing
239	        </span>
240	        <h1 className="text-4xl font-black tracking-tight text-white sm:text-5xl">
241	          Lock in your price <span className="grad-text">today.</span>
242	        </h1>
243	        <p className="mt-4 max-w-md text-[15px] leading-relaxed text-slate-400">
244	          The price you sign up at is the price you renew at — it never increases at renewal.
245	          No lock-in, cancel anytime.
246	        </p>
247	        {props.reviewBadges && <div className="mt-6 flex justify-center">{props.reviewBadges}</div>}
248	      </div>
249	
250	      {/* ── Product tab row ── */}
251	      <div
252	        role="tablist"
253	        aria-label="Product"
254	        className="-mx-5 flex items-center gap-1 overflow-x-auto px-5 pb-1 sm:mx-0 sm:justify-center sm:gap-2 sm:overflow-visible sm:px-0"
255	      >
256	        {PRODUCTS.map(({ id, label, Icon }) => {
257	          const active = product === id;
258	          const a = ACCENTS[id];
