"use client";

import { useEffect, useRef } from "react";

/**
 * Living Infrastructure (v5) signature: an ambient canvas node-field that drifts,
 * links near neighbours, and reacts to the cursor (nearby nodes lean toward it and
 * draw brighter links). Capped particle count + rAF for 60fps; reduced-motion or
 * mobile → a single static frame. Pure canvas, no assets.
 */
export function AmbientField() {
  const ref = useRef<HTMLCanvasElement | null>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    if (!ctx) return;

    const reduce = window.matchMedia?.("(prefers-reduced-motion: reduce)").matches ?? false;
    const dpr = Math.min(window.devicePixelRatio || 1, 2);
    let w = 0, h = 0;
    const mouse = { x: -9999, y: -9999 };

    const COUNT = Math.min(72, Math.floor((window.innerWidth * window.innerHeight) / 26000));
    const pts = Array.from({ length: COUNT }, () => ({
      x: Math.random(), y: Math.random(),
      vx: (Math.random() - 0.5) * 0.00022, vy: (Math.random() - 0.5) * 0.00022,
    }));

    const resize = () => {
      const rect = canvas.getBoundingClientRect();
      w = rect.width; h = rect.height;
      canvas.width = w * dpr; canvas.height = h * dpr;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    };
    resize();

    const draw = () => {
      ctx.clearRect(0, 0, w, h);
      // update + draw nodes
      for (const p of pts) {
        if (!reduce) { p.x += p.vx; p.y += p.vy; if (p.x < 0 || p.x > 1) p.vx *= -1; if (p.y < 0 || p.y > 1) p.vy *= -1; }
        const px = p.x * w, py = p.y * h;
        const dm = Math.hypot(px - mouse.x, py - mouse.y);
        const near = dm < 140;
        ctx.beginPath();
        ctx.arc(px, py, near ? 2.2 : 1.4, 0, Math.PI * 2);
        ctx.fillStyle = near ? "rgba(150,190,255,0.9)" : "rgba(120,150,220,0.5)";
        ctx.fill();
        // link to cursor
        if (near) {
          ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(mouse.x, mouse.y);
          ctx.strokeStyle = `rgba(99,102,241,${0.35 * (1 - dm / 140)})`; ctx.lineWidth = 0.7; ctx.stroke();
        }
      }
      // link near neighbours
      for (let i = 0; i < pts.length; i++) {
        for (let j = i + 1; j < pts.length; j++) {
          const ax = pts[i].x * w, ay = pts[i].y * h, bx = pts[j].x * w, by = pts[j].y * h;
          const d = Math.hypot(ax - bx, ay - by);
          if (d < 120) {
            ctx.beginPath(); ctx.moveTo(ax, ay); ctx.lineTo(bx, by);
            ctx.strokeStyle = `rgba(90,110,200,${0.16 * (1 - d / 120)})`; ctx.lineWidth = 0.6; ctx.stroke();
          }
        }
      }
    };

    let raf = 0;
    const loop = () => { draw(); raf = requestAnimationFrame(loop); };
    if (reduce) draw(); else loop();

    const onMove = (e: MouseEvent) => { const r = canvas.getBoundingClientRect(); mouse.x = e.clientX - r.left; mouse.y = e.clientY - r.top; };
    const onLeave = () => { mouse.x = -9999; mouse.y = -9999; };
    window.addEventListener("resize", resize);
    window.addEventListener("mousemove", onMove);
    window.addEventListener("mouseout", onLeave);
    return () => { cancelAnimationFrame(raf); window.removeEventListener("resize", resize); window.removeEventListener("mousemove", onMove); window.removeEventListener("mouseout", onLeave); };
  }, []);
