  style={{
    background: `radial-gradient(ellipse 45% 100% at 28% 0%, rgba(${accent.aura1},0.16), transparent 72%), radial-gradient(ellipse 38% 100% at 82% 0%, rgba(${accent.aura2},0.12), transparent 72%)`,
